#include <bits/stdc++.h>
using namespace std;
using ll = long long; 
const ll MOD = 998244353; 
int main() {
	// your code goes here
	int t;
	cin>>t; 
	while(t--){
	    int n; 
	    cin>>n; 
	    vector<vector<int>>arr(n + 1); 
	    for(int i = 1;i<=n;i++){
	        int x; 
	        cin>>x; 
	        arr[x].push_back(i); 
	    } 
	    vector<ll>dp(1,1); 
	    for(int x = 1;x < n;x++){
	        vector<int>vt1(x,1),vt2(x,1); 
	        for(int i : arr[x]){
	            int v1 = (i - 1) /2; 
	            int v2 = (n - i) /2;
	            for(int l = 0;l < x;l++){
	                int r = x - l - 1; 
	                int pre = min(l,i) + max(0,i - n + r); 
	                int suf =max(0,l - i +1) + min(r,n - i + 1);
	                int posL = l + 1; 
	                bool goodL =(posL <= i && pre == v1) || (posL >= i && suf == v2); 
	                int posR = n - r; 
	                bool goodR = (posR <= i && pre == v1) || (posR >= i && suf == v2); 
	                vt1[l] &= goodL; 
	                vt2[l] &= goodR; 
	            }
	        }
	        vector<ll>ndp(x + 1,0); 
	        for(int l = 0;l < x;l++){
	            if(vt1[l]){
	                ndp[l + 1] = (ndp[l + 1] + dp[l])%MOD; 
	            }
	            if(vt2[l]){
	                ndp[l] = (ndp[l] + dp[l]) % MOD; 
	            }}
	            dp.swap(ndp);
	        }
	        ll ans = 0;
	        for(int l = 0;l < n;l++){
	            int r = n - l - 1; 
	            bool good = true; 
	            for(int i : arr[n]){
	                int v1 = (i - 1)/2; 
	                int v2 = (n - i)/2; 
	                int pre = min(l,i) + max(0,i - n + r); 
	                int suf = max(0,l - i +1) + min(r,n - i + 1); 
	                int pos = l + 1; 
	                if(!((pos <= i && pre == v1) || (pos >= i && suf == v2))){
	                    good = false; 
	                    break; 
	                }
	            }
	            if(good)ans = (ans + dp[l]) % MOD;
	        }
	        cout<<ans<<endl;}
}
